    # Initialize the dynamic programming table
    dp = [[0] * len(beads) for _ in range(len(beads))]

    # Fill in the first row of the table
    for i in range(len(beads)):
        dp[0][i] = beads[i]

    # Fill in the table using the recurrence relation
    for i in range(1, len(beads)):
        for j in range(len(beads)):
            # Consider all possible combinations of merging two beads
            for k in range(j + 1, len(beads)):
                # Compute the energy released by merging beads j and k
                energy = beads[j] * beads[k] * beads[(k + 1) % len(beads)]
                # Update the maximum energy obtainable
                dp[i][j] = max(dp[i][j], dp[i - 1][k] + energy)

    # Return the maximum energy obtainable
    return max(dp[-1])
