def generate_numbers(n, rules):
    queue = [n]
    seen = set(n)
    while queue:
        num = queue.pop(0)
        for rule in rules:
            new_num = None
            if rule[0] in num:
                new_num = num.replace(rule[0], rule[1])
            if new_num not in seen:
