def max_herb_value(T, M, herbs):
    # Initialize a 2D table to store the results of subproblems
    table = [[0] * (M+1) for _ in range(T+1)]

    # Fill the table with the values from the herbs list
    for t in range(1, T+1):
        for m in range(1, M+1):
            time, value = herbs[m-1]
            table[t][m] = max(table[t-time][m-1] + value, table[t-1][m])

