def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Populate the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # Case 1: Exclude the current item
            dp[i][j] = dp[i][j - 1]
            # Case 2: Include the current item if it fits
            if i - volumes[j - 1] >= 0:
                dp[i][j] = max(dp[i][j], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])

    # Return the minimum remaining space
    return V - dp[V][n]

