def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [[0] * (m+1) for _ in range(n+1)]
    dp[0][0] = 1
    for i in range(1, n+1):
        for j in range(m+1):
            for k in range(a[i-1]+1):
                if j >= k:
                    dp[i][j] += dp[i-1][j-k]
                    dp[i][j] %= MOD
    return dp[n][m]
